import sys
from collections import defaultdict

n, t = map(int, sys.stdin.readline().split())

dp = {(y, 0, 0, 0): 1 for y in range(1, 5)}

for _ in range(1, n):
    ndp = defaultdict(int)
    for (last, direction, peaks, valleys), count in dp.items():
        for y in range(1, 5):
            if y == last:
                continue

            new_direction = 1 if y > last else -1
            new_peaks = peaks
            new_valleys = valleys

            if direction == 1 and new_direction == -1:
                new_peaks += 1
            elif direction == -1 and new_direction == 1:
                new_valleys += 1

            if new_peaks <= t and new_valleys <= t - 1:
                ndp[(y, new_direction, new_peaks, new_valleys)] += count
    dp = ndp

answer = sum(
    count
    for (last, direction, peaks, valleys), count in dp.items()
    if peaks == t and valleys == t - 1
)

print(answer)

import sys

n, t = map(int, sys.stdin.readline().split())

dp = {}
for first in range(1, 5):
    for second in range(1, 5):
        if first != second:
            direction = 1 if second > first else -1
            dp[(second, direction, 0, 0)] = dp.get(
                (second, direction, 0, 0), 0
            ) + 1

for _ in range(2, n):
    new_dp = {}
    for (last, direction, peaks, valleys), count in dp.items():
        for current in range(1, 5):
            if current == last:
                continue

            new_direction = 1 if current > last else -1
            new_peaks = peaks + (direction == 1 and new_direction == -1)
            new_valleys = valleys + (direction == -1 and new_direction == 1)

            if new_peaks <= t and new_valleys <= t - 1:
                state = (current, new_direction, new_peaks, new_valleys)
                new_dp[state] = new_dp.get(state, 0) + count
    dp = new_dp

answer = sum(
    count
    for (_, _, peaks, valleys), count in dp.items()
    if peaks == t and valleys == t - 1
)
print(answer)

